// Auto-generated bundled runtime LUT binaries for offline pro-camera analog emulation.
import { Buffer } from '@craftzdog/react-native-buffer'

const BALI_400_BASE64 =
  ''
const MARTHA_BASE64 =
  ''

export function getBundledLutBytes(id: string): Uint8Array | null {
  if (id === 'bali-400-v1') {
    return new Uint8Array(Buffer.from(BALI_400_BASE64, 'base64'))
  }
  if (id === 'martha-v1') {
    return new Uint8Array(Buffer.from(MARTHA_BASE64, 'base64'))
  }
  return null
}
